-- Check: one row per event with its judges
select g.name as "group", e.name as event, count(a.*) as judges
from public.events e join public.groups g on g.id = e.group_id
left join public.judge_assignments a on a.event_id = e.id and a.is_active
group by g.display_order, g.name, e.display_order, e.name order by g.display_order, e.display_order;
